-- 27 - SAT Practice Test N: new draft set versions with module items in official order (R&W domain blocks; Math skill mean position then difficulty)
-- generated by scripts/prod-open/sat-order-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched; items unchanged, only positions rearranged inside each module.

do $o27$
declare
  v_actor uuid := (select id from profiles where role = 'admin' order by created_at limit 1);
  v_src mock_exam_sets%rowtype; v_new uuid; v_cols text; v_cols_i text; v_moved int; v_bad text; v_diff int;
begin
  for v_src in select * from mock_exam_sets where status = 'published' and archived_at is null and name ~ '^SAT Practice Test [0-9]+$' order by length(name), name loop
    begin
      select count(*) into v_moved from (
  with k as (select i.id, i.section, i.module_key, coalesce(i.route::text, '') as rt, i.position, coalesce(ord.ka, 99) as ka, coalesce(ord.kb, 0) as kb, case i.difficulty when 'easy' then 0 when 'medium' then 1 else 2 end as d
             from mock_exam_set_items i left join (values ('rw','words_in_context',0,0), ('rw','text_structure_purpose',0,1), ('rw','cross_text_connections',0,2), ('rw','central_ideas_details',1,0), ('rw','command_of_evidence_quant',1,1), ('rw','command_of_evidence_text',1,2), ('rw','inferences',1,3), ('rw','form_structure_sense',2,0), ('rw','boundaries',2,0), ('rw','transitions',3,0), ('rw','rhetorical_synthesis',3,1), ('math','probability',3.5,0), ('math','inference_margin_error',8.3,0), ('math','evaluating_statistical_claims',8.3,0), ('math','two_variable_data',9.4,0), ('math','linear_equations_one_var',9.7,0), ('math','linear_functions',11.3,0), ('math','linear_inequalities',12.3,0), ('math','equivalent_expressions',13.2,0), ('math','ratios_rates_units',14.8,0), ('math','percentages',14.8,0), ('math','lines_angles_triangles',14.8,0), ('math','linear_equations_two_var',15.1,0), ('math','systems_linear',15.1,0), ('math','nonlinear_functions',15.6,0), ('math','one_variable_data',16.8,0), ('math','nonlinear_equations_systems',17.1,0), ('math','area_volume',17.1,0), ('math','right_triangles_trigonometry',19.1,0), ('math','circles',19.5,0)) as ord(section, skill, ka, kb) on ord.section = i.section and ord.skill = i.skill_code where i.exam_set_id = v_src.id),
  a as (select k.*, row_number() over (partition by module_key, rt order by ka, kb, d, position) as orn, row_number() over (partition by module_key, rt order by position) as prn from k)
  select a.id, p.position as new_position, a.position as old_position, a.module_key, a.rt from a join a p on p.module_key = a.module_key and p.rt = a.rt and p.prn = a.orn) np where np.new_position <> np.old_position;
      if v_moved = 0 then raise notice '% already in official order - skipped', v_src.name; continue; end if;
      if exists (select 1 from mock_exam_sets where set_group_id = v_src.set_group_id and status = 'draft') then raise notice '% a draft version already exists - skipped (publish/discard it, then re-run)', v_src.name; continue; end if;
      perform pg_advisory_xact_lock(hashtextextended('mock_exam_new_version:' || v_src.set_group_id::text, 0));
      v_new := gen_random_uuid();
      select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_sets' and is_generated = 'NEVER' and column_name not in ('id', 'version_no', 'status', 'created_by', 'created_at', 'published_at', 'published_by', 'archived_at', 'access_tier', 'readiness_status', 'readiness_report', 'readiness_checked_at');
      execute format('insert into mock_exam_sets (id, version_no, status, created_by, access_tier, %s) select $1, $2, ''draft'', $3, ''tutoring'', %s from mock_exam_sets where id = $4', v_cols, v_cols)
        using v_new, (select max(version_no) + 1 from mock_exam_sets where set_group_id = v_src.set_group_id), v_actor, v_src.id;
      select string_agg(quote_ident(column_name), ', ' order by ordinal_position), string_agg(case column_name when 'position' then 'np.new_position' else 'i.' || quote_ident(column_name) end, ', ' order by ordinal_position)
        into v_cols, v_cols_i from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_set_items' and is_generated = 'NEVER' and column_name not in ('id', 'exam_set_id', 'created_at');
      execute format('insert into mock_exam_set_items (exam_set_id, %s) select $1, %s from mock_exam_set_items i join (
  with k as (select i.id, i.section, i.module_key, coalesce(i.route::text, '''') as rt, i.position, coalesce(ord.ka, 99) as ka, coalesce(ord.kb, 0) as kb, case i.difficulty when ''easy'' then 0 when ''medium'' then 1 else 2 end as d
             from mock_exam_set_items i left join (values (''rw'',''words_in_context'',0,0), (''rw'',''text_structure_purpose'',0,1), (''rw'',''cross_text_connections'',0,2), (''rw'',''central_ideas_details'',1,0), (''rw'',''command_of_evidence_quant'',1,1), (''rw'',''command_of_evidence_text'',1,2), (''rw'',''inferences'',1,3), (''rw'',''form_structure_sense'',2,0), (''rw'',''boundaries'',2,0), (''rw'',''transitions'',3,0), (''rw'',''rhetorical_synthesis'',3,1), (''math'',''probability'',3.5,0), (''math'',''inference_margin_error'',8.3,0), (''math'',''evaluating_statistical_claims'',8.3,0), (''math'',''two_variable_data'',9.4,0), (''math'',''linear_equations_one_var'',9.7,0), (''math'',''linear_functions'',11.3,0), (''math'',''linear_inequalities'',12.3,0), (''math'',''equivalent_expressions'',13.2,0), (''math'',''ratios_rates_units'',14.8,0), (''math'',''percentages'',14.8,0), (''math'',''lines_angles_triangles'',14.8,0), (''math'',''linear_equations_two_var'',15.1,0), (''math'',''systems_linear'',15.1,0), (''math'',''nonlinear_functions'',15.6,0), (''math'',''one_variable_data'',16.8,0), (''math'',''nonlinear_equations_systems'',17.1,0), (''math'',''area_volume'',17.1,0), (''math'',''right_triangles_trigonometry'',19.1,0), (''math'',''circles'',19.5,0)) as ord(section, skill, ka, kb) on ord.section = i.section and ord.skill = i.skill_code where i.exam_set_id = $2),
  a as (select k.*, row_number() over (partition by module_key, rt order by ka, kb, d, position) as orn, row_number() over (partition by module_key, rt order by position) as prn from k)
  select a.id, p.position as new_position, a.position as old_position, a.module_key, a.rt from a join a p on p.module_key = a.module_key and p.rt = a.rt and p.prn = a.orn) np on np.id = i.id where i.exam_set_id = $2', v_cols, v_cols_i) using v_new, v_src.id;
      -- items unchanged: same (problem_version_id, module_key, route) multiset, same count
      select count(*) into v_diff from (
        (select problem_version_id, module_key, route, section from mock_exam_set_items where exam_set_id = v_src.id except all select problem_version_id, module_key, route, section from mock_exam_set_items where exam_set_id = v_new)
        union all
        (select problem_version_id, module_key, route, section from mock_exam_set_items where exam_set_id = v_new except all select problem_version_id, module_key, route, section from mock_exam_set_items where exam_set_id = v_src.id)) d;
      if v_diff <> 0 then raise exception 'items changed during reorder (% differences)', v_diff; end if;
      if not coalesce((public.mock_exam_validate_mst_set(v_new)->>'ready')::boolean, false) then raise exception 'validation failed %', public.mock_exam_validate_mst_set(v_new)::text; end if;
      select string_agg(x.problem_id::text || ':' || x.issue, ', ') into v_bad from (select * from public.mock_exam_set_item_issues(v_new) where issue is not null limit 5) x;
      if v_bad is not null then raise exception 'item issues %', v_bad; end if;
      update mock_exam_sets set readiness_status = 'ready', readiness_report = public.mock_exam_validate_mst_set(v_new) || jsonb_build_object('shortfalls', '[]'::jsonb, 'checkedAt', now(), 'officialOrder27', true), readiness_checked_at = now() where id = v_new;
      raise notice '% new draft version created (% items moved) -> %', v_src.name, v_moved, v_new;
    exception when others then raise notice '% SKIPPED: %', v_src.name, sqlerrm;
    end;
  end loop;
end
$o27$;
